/// `tests/bugs/mesh/bug25142`
#[test]
#[should_panic]
fn bug25142() {
    expected_failure(|| {
        let mut d = Draw::new();
        d.r#box(&["b1", "20", "10", "10"])?;
        d.r#box(&["b2", "10", "10", "10"])?;
        d.bclear(&[])?;
        d.baddobjects(&["b1", "b2"])?;
        d.bfillds(&[])?;
        d.bbuild(&["r"])?;
        d.explode(&["r"])?;
        d.tolerance(&["r"])?;
        d.checkshape(&["r"])?;
        d.bopargcheck(&["r", "#F"])?;
        d.bopargcheck(&["r_1", "r_2", "-F", "#F"])?;
        d.incmesh(&["r_1", "0.1"])?;
        d.tricheck(&["r_1"])?;
        d.incmesh(&["r_2", "0.1"])?;
        d.tricheck(&["r_2"])?;
        d.tricheck(&["r_1"])?;
        d.tclean(&["r"])?;
        d.tricheck(&["r_1"])?;
        Ok(())
    })
}

/// `tests/bugs/mesh/bug25157`
/// kentron: sub-shapes named by OCCT's enumeration are selected by position (draw_selectors.json)
#[test]
fn bug25157() -> DrawResult<()> {
    let mut d = Draw::new();
    d.pcone(&["Cone", "6", "0", "10", "180"])?;
    d.pcylinder(&["Cylinder", "1", "6", "360"])?;
    d.ttranslate(&["Cylinder", "0", "3", "1"])?;
    d.bcut(&["Cut", "Cone", "Cylinder"])?;
    d.explode(&["Cut", "F"])?;
    d.nearest(&["Cut_1", "Cut", "F", "-6.99447e-06", "2.51981", "3.23936", "103.804"])?;
    d.tclean(&["Cut_1"])?;
    d.incmesh(&["Cut_1", "0.1"])?;
    d.checktrinfo(&["Cut_1", "-tri", "-nod"])?;
    Ok(())
}

